#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int removeCoveredIntervals(vector<vector<int>>& intervals) {
        sort(intervals.begin(), intervals.end(), [](auto& a, auto& b) {
            return a[0] < b[0] || (a[0] == b[0] && a[1] > b[1]);
        });

        int count = 0, end = 0;
        for (auto& i : intervals) {
            if (i[1] > end) {
                ++count;
                end = i[1];
            }
        }
        return count;
    }
};
